ntract.","tc":2.333,"lc":2,"tl":1.5},{"itemOrder":3,"sourceItemId":"Number 3","sourceMaterial":"Day 2","sourceCciId":"cci-004","sourceCvrId":7,"termVi":"Ký một cái hợp đồng","termEn":"Sign a contract","promptVi":"Tôi rất vui mừng khi cuối cùng cũng được ký một cái hợp đồng lao động với đối tác lớn.","promptEn":"I am very happy to finally sign an employment contract with the major partner.","tc":2.333,"lc":2,"tl":1.5},{"itemOrder":4,"sourceItemId":"Number 4","sourceMaterial":"Day 2","sourceCciId":"cci-004","sourceCvrId":7,"termVi":"Trước tiên","termEn":"First / firstly / first off","promptVi":"Trước tiên bạn cần hoàn thành bản báo cáo này trước khi tham gia cuộc họp quan trọng sắp tới.","promptEn":"First off, you need to complete this report before participating in the upcoming important meeting.","tc":2.333,"lc":2,"tl":1.5},{"itemOrder":5,"sourceItemId":"Number 5","sourceMaterial":"Day 2","sourceCciId":"cci-004","sourceCvrId":7,"termVi":"Thương lượng","termEn":"Negotiate","promptVi":"Chúng tôi đang cố gắng thương lượng với nhà cung cấp để có được mức giá ưu đãi tốt nhất.","promptEn":"We are trying to negotiate with the supplier to get the best discounted price.","tc":2.333,"lc":2,"tl":1.5},{"itemOrder":6,"sourceItemId":"Number 6","sourceMaterial":"Day 2","sourceCciId":"cci-004","sourceCvrId":7,"termVi":"Ồn ào / to mồm","termEn":"Noisy / loud-mouthed","promptVi":"Những người khách ở bàn bên cạnh nói chuyện quá ồn ào làm ảnh hưởng đến mọi người xung quanh.","promptEn":"The guests at the next table were talking too loudly, affecting everyone around them.","tc":2.333,"lc":2,"tl":1.5},{"itemOrder":7,"sourceItemId":"Number 7","sourceMaterial":"Day 2","sourceCciId":"cci-004","sourceCvrId":7,"termVi":"Đồng nghiệp","termEn":"Coworker / colleague / office buddy","promptVi":"Tôi luôn nhận được sự hỗ trợ nhiệt tình từ các đồng nghiệp thân thiện trong văn phòng làm việc.","promptEn":"I always receive enthusiastic support from friendly colleagues in the office.","tc":2.333,"lc":2,"tl":1.5}]},{"sessionOrder":5,"name":"Test 05","description":"Bộ test mới 7 sessions","sourceCciId":"cci-005","targetCvrOhm":9,"introTextVi":"Session 5. CVR 9. CCI 6. Taichi.","introTextEn":"Session 5. CVR 9. CCI 6. Taichi.","items":[{"itemOrder":1,"sourceItemId":"Number 1","sourceMaterial":"Day 2","sourceCciId":"cci-005","sourceCvrId":9,"termVi":"Quá nhanh","termEn":"(Way) too fast","promptVi":"Thời gian trôi qua quá nhanh và chúng tôi cần phải tập trung để hoàn thành kế hoạch đúng hạn.","promptEn":"Time passes too fast, and we need to focus to complete the plan on time.","tc":3,"lc":2,"tl":1.5},{"itemOrder":2,"sourceItemId":"Number 2","sourceMaterial":"Day 2","sourceCciId":"cci-005","sourceCvrId":9,"termVi":"Nhiều khi / có mấy lúc","termEn":"Sometimes / once in a while / at times","promptVi":"Nhiều khi tôi cảm thấy mệt mỏi vì áp lực công việc nhưng tôi vẫn không muốn bỏ cuộc đâu.","promptEn":"Sometimes I feel tired because of work pressure, but I still do not want to give up.","tc":3,"lc":2,"tl":1.5},{"itemOrder":3,"sourceItemId":"Number 3","sourceMaterial":"Day 2","sourceCciId":"cci-005","sourceCvrId":9,"termVi":"Tôi e là không","termEn":"I'm afraid not","promptVi":"Tôi e là không thể tham gia buổi tiệc tối nay cùng các bạn vì bận việc gia đình riêng.","promptEn":"I am afraid not to join the party tonight with you because of personal family business.","tc":3,"lc":2,"tl":1.5},{"itemOrder":4,"sourceItemId":"Number 4","sourceMaterial":"Day 2","sourceCciId":"cci-005","sourceCvrId":9,"termVi":"(Ý anh) là sao?","termEn":"What'd you mean?","promptVi":"Ý anh là sao khi nói rằng chúng tôi cần phải thay đổi toàn bộ nội dung thiết kế này?","promptEn":"What do you mean by saying that we need to change the entire content of this design?","tc":3,"lc":2,"tl":1.5},{"itemOrder":5,"sourceItemId":"Number 5","sourceMaterial":"Day 2","sourceCciId":"cci-005","sourceCvrId":9,"termVi":"Phức tạp","termEn":"Complicated / complex / like a mess","promptVi":"Quy trình giải quyết các thủ tục