2,"tl":1.5},{"itemOrder":3,"sourceItemId":"Number 3","sourceMaterial":"Day 2","sourceCciId":"cci-006","sourceCvrId":11,"termVi":"Đại dịch","termEn":"Pandemic / epidemic","promptVi":"Nhiều doanh nghiệp nhỏ đã phải đóng cửa vĩnh viễn vì không thể vượt qua giai đoạn đại dịch này.","promptEn":"Many small businesses had to shut down permanently because they could not overcome this pandemic period.","tc":3.667,"lc":2,"tl":1.5},{"itemOrder":4,"sourceItemId":"Number 4","sourceMaterial":"Day 2","sourceCciId":"cci-006","sourceCvrId":11,"termVi":"Chính phủ Trung Quốc","termEn":"Chinese government","promptVi":"Chính phủ Trung Quốc đã ban hành một số chính sách mới nhằm kiểm soát hoạt động xuất nhập khẩu.","promptEn":"The Chinese government has issued several new policies to strictly control import and export activities.","tc":3.667,"lc":2,"tl":1.5},{"itemOrder":5,"sourceItemId":"Number 5","sourceMaterial":"Day 2","sourceCciId":"cci-006","sourceCvrId":11,"termVi":"đóng cửa","termEn":"Shut down","promptVi":"Cửa hàng bán lẻ đó đã quyết định đóng cửa để tập trung kinh doanh trên các nền tảng số.","promptEn":"That retail store decided to shut down to focus on doing business on digital platforms.","tc":3.667,"lc":2,"tl":1.5},{"itemOrder":6,"sourceItemId":"Number 6","sourceMaterial":"Day 2","sourceCciId":"cci-006","sourceCvrId":11,"termVi":"Nỗi đau thật sự","termEn":"Real pain point","promptVi":"Việc không thể tối ưu hóa chi phí sản xuất đang là nỗi đau thật sự của doanh nghiệp này.","promptEn":"Being unable to optimize production costs is currently a real pain point for this business.","tc":3.667,"lc":2,"tl":1.5},{"itemOrder":7,"sourceItemId":"Number 7","sourceMaterial":"Day 2","sourceCciId":"cci-006","sourceCvrId":11,"termVi":"Thượng Hải","termEn":"Shanghai","promptVi":"Thành phố Thượng Hải là trung tâm tài chính và thương mại vô cùng lớn và phát triển sầm uất.","promptEn":"Shanghai city is an extremely large and busy financial and commercial center.","tc":3.667,"lc":2,"tl":1.5}]},{