oard","promptVi":"Khách hàng có thể liên hệ trực tiếp với tổng đài Viettel để được hỗ trợ xử lý sự cố.","promptEn":"Customers can contact the Viettel call center directly for support in resolving issues.","tc":4.333,"lc":2,"tl":1.5},{"itemOrder":6,"sourceItemId":"Number 6","sourceMaterial":"Day 2","sourceCciId":"cci-007","sourceCvrId":13,"termVi":"Dài dòng","termEn":"Lengthy / wordy","promptVi":"Bản báo cáo tài chính này quá dài dòng và không tập trung vào các điểm mấu chốt quan trọng.","promptEn":"This financial report is too lengthy and does not focus on key important points.","tc":4.333,"lc":2,"tl":1.5},{"itemOrder":7,"sourceItemId":"Number 7","sourceMaterial":"Day 2","sourceCciId":"cci-007","sourceCvrId":13,"termVi":"Trung Đông","termEn":"Middle East","promptVi":"Tình hình kinh tế tại khu vực Trung Đông đang có những biến động rất lớn thời gian gần đây.","promptEn":"The economic situation in the Middle East has had very large changes recently.","tc":4.333,"lc":2,"tl":1.5}]}],"issues":[]}$manifest$::jsonb
